B.cwh=new A.K(B.vA,["Masalah koneksi rekaman","Ini adalah sesi rekaman perangkat, tetapi kanal koneksi belum pulih sehingga rekaman belum dapat diakhiri. Kembali ke daftar dan tunggu perangkat tersambung kembali, atau sambungkan ulang dari halaman perangkat sebelum mengakhiri.","Izin mikrofon diperlukan","Rekaman real-time memerlukan akses mikrofon. Aktifkan izin mikrofon di pengaturan sistem sebelum melanjutkan.","Tidak dapat memulai layanan halaman rekaman","Sedang menandai...","Ditandai","Debug rekaman","Durasi rekaman","Status rekaman: {state}","Belum dimulai","Merekam","Dijeda","Dihentikan","Bahasa sumber","Bahasa target (opsional)","Terjemahan","Koneksi ASR: {state}","Berkas audio: {path}","Foto terbaru: {path}","Foto diambil: {count}","Diagnostik: {message}","(Tidak ada)","Belum ada transkrip","Belum ada agenda real-time","Transkrip real-time (paragraf)","Pembicara tanpa label","Agenda AI","Agenda ke-{seq}","Klien jaringan belum disuntikkan. Berjalan dalam mode mock lokal.","Tidak ada tambahan","{count} item ditarik","Tidak diketahui","Membuat","Berhasil","Gagal","Tidak ada konten","Selesai","Gambar saat ini: tangkapan asli","Gambar saat ini: berkas yang diedit","|  {message}","Status sinkronisasi: {state}  recordId={recordId}  seq={seq}{message}"],t.w)
B.cwi=new A.K(B.vA,["Problem mit der Aufnahmeverbindung","Dies ist eine Ger\xe4teaufnahmesitzung, aber der Verbindungskanal wurde noch nicht wiederhergestellt. Die Aufnahme kann daher noch nicht beendet werden. Kehren Sie zur Liste zur\xfcck und warten Sie, bis das Ger\xe4t erneut verbunden ist, oder verbinden Sie es auf der Ger\xe4teseite erneut, bevor Sie beenden.","Mikrofonberechtigung erforderlich","F\xfcr Echtzeitaufnahmen ist Mikrofonzugriff erforderlich. Aktivieren Sie die Mikrofonberechtigung in den Systemeinstellungen, bevor Sie fortfahren.","Der Dienst der Aufnahmeseite konnte nicht gestartet werden","Markierung l\xe4uft...","Markiert","Aufnahme-Debugging","Aufnahmedauer","Aufnahmestatus: {state}","Nicht gestartet","Aufnahme l\xe4uft","Pausiert","Gestoppt","Ausgangssprache","Zielsprache (optional)","\xdcbersetzung","ASR-Verbindung: {state}","Audiodatei: {path}","Neuestes Foto: {path}","Aufgenommene Fotos: {count}","Diagnose: {message}","(Keine)","Noch kein Transkript","Noch keine Echtzeit-Agenda","Echtzeittranskript (Abs\xe4tze)","Nicht markierter Sprecher","KI-Agenda","Tagesordnung #{seq}","Kein Netzwerkclient injiziert. Lokaler Mock-Modus wird verwendet.","Kein Inkrement","{count} Elemente abgerufen","Unbekannt","Wird generiert","Erfolg","Fehlgeschlagen","Kein Inhalt","Fertig","Aktuelles Bild: Originalaufnahme","Aktuelles Bild: bearbeitete Datei","|  {message}","Synchronisierungsstatus: {state}  recordId={recordId}  seq={seq}{message}"],t.w)
